WITH clean AS (SELECT DISTINCT TRIM(record_id) AS record_id,TRIM(business_date) AS business_date,TRIM(store_id) AS store_id,CASE TRIM(channel) WHEN '外卖' THEN 'delivery' ELSE TRIM(channel) END AS channel,TRIM(fulfilled_orders) AS fulfilled_orders,TRIM(refunded_orders) AS refunded_orders,TRIM(gross_sales_cents) AS gross_sales_cents,TRIM(merchant_discount_cents) AS merchant_discount_cents,TRIM(platform_discount_cents) AS platform_discount_cents,TRIM(customer_paid_cents) AS customer_paid_cents,TRIM(refund_cents) AS refund_cents,TRIM(platform_subsidy_cents) AS platform_subsidy_cents,TRIM(food_cost_cents) AS food_cost_cents,TRIM(packaging_cost_cents) AS packaging_cost_cents,TRIM(platform_fee_cents) AS platform_fee_cents,TRIM(payment_fee_cents) AS payment_fee_cents,TRIM(delivery_cost_cents) AS delivery_cost_cents,TRIM(advertising_cost_cents) AS advertising_cost_cents FROM raw) SELECT CASE WHEN business_date < '2026-10-19' THEN 'W1' ELSE 'W2' END week, COUNT(*), SUM(CAST(fulfilled_orders AS INTEGER)), SUM(CAST(gross_sales_cents AS INTEGER)-CAST(merchant_discount_cents AS INTEGER)-CAST(refund_cents AS INTEGER)), SUM(CAST(gross_sales_cents AS INTEGER)-CAST(merchant_discount_cents AS INTEGER)-CAST(refund_cents AS INTEGER)-CAST(food_cost_cents AS INTEGER)-CAST(packaging_cost_cents AS INTEGER)-CAST(platform_fee_cents AS INTEGER)-CAST(payment_fee_cents AS INTEGER)-CAST(delivery_cost_cents AS INTEGER)-CAST(advertising_cost_cents AS INTEGER)) FROM clean GROUP BY week ORDER BY week;
